-- Generated by Supabase CLI. Shared identity/entries/history remain the source
-- of truth. Unsupported competitions are drafts, never disguised NFL pools.
alter table public.goat_leagues drop constraint goat_leagues_strategy_check;
alter table public.goat_leagues add constraint goat_leagues_strategy_check check(strategy in
 ('ranked_ats_v1','ncaa_bracket_v1','cross_sport_playoffs_v1','fantasy_h2h_2026_v1','mlb_postseason_v1'));
alter table public.goat_leagues add column game_key text check(game_key in
 ('first-and-baa','horns-and-hoops','goat-crossover','league-of-greatness','goat-classic'));

create table public.goat_bracket_config (
 league_id uuid primary key references public.goat_leagues(id),
 main_lock_at timestamptz not null,
 schedule_source text not null check(schedule_source like 'https://%')
);
create table public.goat_bracket_nodes (
 id uuid primary key default gen_random_uuid(), league_id uuid not null references public.goat_leagues(id),
 code text not null check(length(code) between 1 and 80), stage integer not null check(stage between 0 and 6),
 starts_at timestamptz, home_team text, away_team text,
 home_from uuid references public.goat_bracket_nodes(id), away_from uuid references public.goat_bracket_nodes(id),
 source_url text not null check(source_url like 'https://%'),
 winner text, home_score integer check(home_score>=0), away_score integer check(away_score>=0),
 result_source text check(result_source like 'https://%'), finalized_at timestamptz,
 unique(league_id,code),
 check((home_team is null)<>(home_from is null)),check((away_team is null)<>(away_from is null)),
 check(home_team is null or length(btrim(home_team)) between 1 and 150),
 check(away_team is null or length(btrim(away_team)) between 1 and 150),
 check(home_team is null or away_team is null or home_team<>away_team),
 check(home_from is null or away_from is null or home_from<>away_from),
 check((winner is null)=(home_score is null) and (winner is null)=(away_score is null)),
 check((winner is null)=(result_source is null) and (winner is null)=(finalized_at is null))
);
create table public.goat_bracket_submissions (
 league_id uuid references public.goat_leagues(id),user_id uuid references auth.users(id),
 championship_total integer not null check(championship_total between 0 and 10000),
 submitted_at timestamptz not null default now(),primary key(league_id,user_id)
);
create table public.goat_bracket_picks (
 node_id uuid references public.goat_bracket_nodes(id),user_id uuid references auth.users(id),
 team text not null check(length(btrim(team)) between 1 and 150),
 submitted_at timestamptz not null default now(),primary key(node_id,user_id)
);
create index goat_bracket_nodes_league on public.goat_bracket_nodes(league_id,stage);
create index goat_bracket_picks_user on public.goat_bracket_picks(user_id);
do $$ declare t text; begin
 foreach t in array array['goat_bracket_config','goat_bracket_nodes','goat_bracket_submissions','goat_bracket_picks'] loop
  execute format('alter table public.%I enable row level security',t);
  execute format('revoke all on public.%I from public,anon,authenticated',t);
  execute format('grant select on public.%I to authenticated',t);
  execute format('create policy live_session on public.%I as restrictive for all to authenticated using((select public.goat_session_valid())) with check((select public.goat_session_valid()))',t);
 end loop;
end $$;
create policy bracket_config_member on public.goat_bracket_config for select to authenticated using(public.goat_can_view(league_id));
create policy bracket_nodes_member on public.goat_bracket_nodes for select to authenticated using(public.goat_can_view(league_id));
create policy bracket_submission_private on public.goat_bracket_submissions for select to authenticated using
 (public.goat_can_view(league_id) and (user_id=auth.uid() or exists(select 1 from public.goat_bracket_config c where c.league_id=goat_bracket_submissions.league_id and c.main_lock_at<=now())));
create policy bracket_pick_private on public.goat_bracket_picks for select to authenticated using(exists
 (select 1 from public.goat_bracket_nodes n join public.goat_bracket_config c on c.league_id=n.league_id
 where n.id=node_id and public.goat_can_view(n.league_id) and
 (user_id=auth.uid() or (case when n.stage=0 then n.starts_at else c.main_lock_at end)<=now())));

-- Only trusted dispatch calls these helpers. Stage validation prevents cycles.
create function public.goat_bracket_candidates(nid uuid) returns table(team text)
 language sql stable security definer set search_path='' as $$
 with recursive tree as (
 select n.* from public.goat_bracket_nodes n where n.id=nid
 union all select n.* from public.goat_bracket_nodes n join tree t on (n.id=t.home_from or n.id=t.away_from) and t.winner is null
 ) select winner from tree where winner is not null union select home_team from tree where home_team is not null and winner is null union select away_team from tree where away_team is not null and winner is null;
$$;
create function public.goat_bracket_standings(lid uuid) returns jsonb
 language sql stable security definer set search_path='' as $$
 with scores as (
 select e.user_id,p.display_name,coalesce((select sum((array[1,2,3,5,7,9,11])[n.stage+1])
 from public.goat_bracket_picks k join public.goat_bracket_nodes n on n.id=k.node_id
 where k.user_id=e.user_id and n.league_id=lid and n.winner=k.team),0) as points,
 (select count(*) from public.goat_bracket_picks k join public.goat_bracket_nodes n on n.id=k.node_id
 where k.user_id=e.user_id and n.league_id=lid and n.winner=k.team) as correct,
 case when (select main_lock_at from public.goat_bracket_config where league_id=lid)<=now() then s.championship_total end as championship_total,
 (select abs(s.championship_total-n.home_score-n.away_score) from public.goat_bracket_nodes n
 where n.league_id=lid and n.stage=6 and n.winner is not null) as tiebreak_error
 from public.goat_entries e join public.goat_profiles p on p.user_id=e.user_id
 left join public.goat_bracket_submissions s on s.league_id=e.league_id and s.user_id=e.user_id
 where e.league_id=lid and e.status='approved'
 ), ranked as (select *,dense_rank() over(order by points desc,tiebreak_error asc nulls last) as rank from scores)
 select coalesce(jsonb_agg(to_jsonb(ranked) order by rank,display_name),'[]') from ranked;
$$;
revoke all on function public.goat_bracket_candidates(uuid),public.goat_bracket_standings(uuid) from public,anon,authenticated;

alter function public.goat_command(jsonb) rename to goat_command_v2;
alter function public.goat_query(jsonb) rename to goat_query_v2;
revoke all on function public.goat_command_v2(jsonb),public.goat_query_v2(jsonb) from public,anon,authenticated;
create function public.goat_command(p jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
declare actor uuid:=public.goat_actor(); op text:=p->>'op'; lid uuid; l public.goat_leagues;
 c public.goat_bracket_config; n public.goat_bracket_nodes; f public.goat_bracket_nodes;
 eid uuid; item jsonb; selected text; home text; away text; vstage integer; invalid boolean;
 strategy text; sport text; key text:=p->>'game_key'; before_result jsonb;
begin
 if op='game_draft_create' then
  case key
   when 'first-and-baa' then strategy:='ranked_ats_v1';sport:='NFL';
   when 'horns-and-hoops' then strategy:='ncaa_bracket_v1';sport:='NCAA_MBB';
   when 'goat-crossover' then strategy:='cross_sport_playoffs_v1';sport:='NBA_NHL';
   when 'league-of-greatness' then strategy:='fantasy_h2h_2026_v1';sport:='NFL_FANTASY';
   when 'goat-classic' then strategy:='mlb_postseason_v1';sport:='MLB';
   else raise exception 'unsupported_game_draft';
  end case;
  -- This is a project shell, not approval of rules or acceptance of live entries.
  insert into public.goat_leagues(owner_id,name,sport,season,strategy,game_key,rules)
  values(actor,p->>'name',sport,p->>'season',strategy,key,jsonb_build_object('approved',false,
   'source_reference','Founder GOAT Games architecture','unresolved',jsonb_build_array('Competition configuration and launch review required')))
  returning id into eid;
  if key='first-and-baa' then
   update public.goat_leagues set rules='{"approved":false,"max_points":61,"tiebreaker":"ats_record","source_reference":"Founder Super Bowl LXI budget and NFL workbook","unresolved":["Official events, round deadlines and outstanding NFL policies required"]}' where id=eid;
  elsif key='horns-and-hoops' then
   if p ? 'main_lock_at' then
    if (p->>'main_lock_at') is null or (p->>'main_lock_at')::timestamptz<=now() then raise exception 'invalid_deadline'; end if;
    insert into public.goat_bracket_config values(eid,(p->>'main_lock_at')::timestamptz,p->>'schedule_source');
   end if;
   update public.goat_leagues set rules='{"approved":false,"source_reference":"Adam Brown October 14, 2026 scoring and lock instructions","points":[1,2,3,5,7,9,11],"tiebreaker":"championship_total_closest","unresolved":["Official tournament field, schedule and result sources required; launch review pending"]}' where id=eid;
  end if;
  insert into public.goat_audit(actor_id,action,entity_id,detail) values(actor,op,eid,p);
  return jsonb_build_object('id',eid,'status','draft','game_key',key);
 end if;
 -- Resolve identities from database parents, never trust caller-supplied owner
 -- or a mismatched league_id to authorize a node/round/game operation.
 if p ? 'node_id' then select league_id into lid from public.goat_bracket_nodes where id=(p->>'node_id')::uuid;
 elsif p ? 'round_id' then select league_id into lid from public.goat_rounds where id=(p->>'round_id')::uuid;
 elsif p ? 'game_id' then select r.league_id into lid from public.goat_games g join public.goat_rounds r on r.id=g.round_id where g.id=(p->>'game_id')::uuid;
 else lid:=(p->>'league_id')::uuid; end if;
 if lid is null and op like 'bracket_%' then raise exception 'league_not_found'; end if;
 if lid is not null then select * into l from public.goat_leagues where id=lid for update; end if;
 if op like 'bracket_%' and l.strategy is distinct from 'ncaa_bracket_v1' then raise exception 'bracket_league_required'; end if;
 if l.strategy='ncaa_bracket_v1' then
  if l.status='final' then raise exception 'league_final'; end if;
  if op not in ('enroll','bracket_submit','bracket_qualifying_pick') and l.owner_id<>actor then raise exception 'commissioner_required' using errcode='42501'; end if;
  select * into c from public.goat_bracket_config where league_id=lid;
  if op in ('bracket_submit','bracket_qualifying_pick') and not exists(select 1 from public.goat_entries where league_id=lid and user_id=actor and status='approved') then raise exception 'approved_entry_required' using errcode='42501'; end if;
  eid:=lid;
  case op
  when 'league_rules' then
   if l.status<>'draft' then raise exception 'rules_frozen'; end if;
   if p->'rules'->'points' is distinct from '[1,2,3,5,7,9,11]'::jsonb or p->'rules'->>'tiebreaker' is distinct from 'championship_total_closest' then raise exception 'founder_rules_mismatch'; end if;
   update public.goat_leagues set rules=p->'rules' where id=lid;
  when 'bracket_configure' then
   if l.status<>'draft' or exists(select 1 from public.goat_bracket_nodes where league_id=lid) then raise exception 'empty_draft_schedule_required'; end if;
   if (p->>'main_lock_at') is null or (p->>'main_lock_at')::timestamptz<=now() then raise exception 'invalid_deadline'; end if;
   insert into public.goat_bracket_config values(lid,(p->>'main_lock_at')::timestamptz,p->>'schedule_source')
   on conflict(league_id) do update set main_lock_at=excluded.main_lock_at,schedule_source=excluded.schedule_source;
  when 'bracket_schedule_import' then
   if c.league_id is null then raise exception 'bracket_schedule_configuration_required'; end if;
   if l.status<>'draft' or exists(select 1 from public.goat_bracket_nodes where league_id=lid) then raise exception 'empty_draft_schedule_required'; end if;
   if jsonb_typeof(p->'nodes') is distinct from 'array' or jsonb_array_length(p->'nodes') not between 63 and 95 then raise exception 'complete_schedule_required'; end if;
   for item in select value from jsonb_array_elements(p->'nodes') order by (value->>'stage')::integer loop
    if item ? 'home_from_code' then
     select id into eid from public.goat_bracket_nodes where league_id=lid and code=item->>'home_from_code';
     if eid is null then raise exception 'invalid_bracket_feeder'; end if;
     item:=item||jsonb_build_object('home_from',eid);
    end if;
    if item ? 'away_from_code' then
     select id into eid from public.goat_bracket_nodes where league_id=lid and code=item->>'away_from_code';
     if eid is null then raise exception 'invalid_bracket_feeder'; end if;
     item:=item||jsonb_build_object('away_from',eid);
    end if;
    perform public.goat_command(item||jsonb_build_object('op','bracket_node_create','league_id',lid));
   end loop;
   eid:=lid;
  when 'bracket_node_create' then
   if c.league_id is null then raise exception 'bracket_schedule_configuration_required'; end if;
   if l.status<>'draft' then raise exception 'schedule_frozen'; end if;
   vstage:=(p->>'stage')::integer;
   if vstage is null or vstage not between 0 and 6 then raise exception 'invalid_bracket_stage'; end if;
   if vstage in (0,1) and ((p->>'starts_at') is null or (p->>'starts_at')::timestamptz<=now()) then raise exception 'invalid_deadline'; end if;
   if vstage=0 and (p ? 'home_from' or p ? 'away_from') then raise exception 'invalid_bracket_feeder'; end if;
   if vstage>1 and ((p->>'home_from') is null or (p->>'away_from') is null) then raise exception 'bracket_feeders_required'; end if;
   if vstage=1 and (p->>'starts_at')::timestamptz<c.main_lock_at then raise exception 'invalid_deadline'; end if;
   for selected in select x.value from jsonb_each_text(p) x where x.key in ('home_from','away_from') and x.value is not null loop
    select * into f from public.goat_bracket_nodes where id=selected::uuid;
    if f.id is null or f.league_id<>lid or f.stage<>vstage-1 then raise exception 'invalid_bracket_feeder'; end if;
   end loop;
   insert into public.goat_bracket_nodes(league_id,code,stage,starts_at,home_team,away_team,home_from,away_from,source_url)
   values(lid,p->>'code',vstage,(p->>'starts_at')::timestamptz,p->>'home_team',p->>'away_team',(p->>'home_from')::uuid,(p->>'away_from')::uuid,p->>'source_url') returning id into eid;
  when 'league_open' then
   if c.league_id is null then raise exception 'bracket_schedule_configuration_required'; end if;
   if l.status<>'draft' or coalesce(l.rules->>'approved','false')<>'true' or coalesce(length(btrim(l.rules->>'source_reference')),0)=0 or
    l.rules->'points' is distinct from '[1,2,3,5,7,9,11]'::jsonb or l.rules->>'tiebreaker' is distinct from 'championship_total_closest' or
    coalesce(l.rules->'unresolved','[]')<>'[]'::jsonb or coalesce(length(btrim(p->>'reason')),0)=0 then raise exception 'rules_approval_required'; end if;
   for vstage in 1..6 loop
    if (select count(*) from public.goat_bracket_nodes where league_id=lid and goat_bracket_nodes.stage=vstage)<>(2^(6-vstage))::integer then raise exception 'complete_63_game_bracket_required'; end if;
   end loop;
   if c.main_lock_at<=now() or c.main_lock_at is distinct from (select min(starts_at) from public.goat_bracket_nodes where league_id=lid and goat_bracket_nodes.stage=1) then raise exception 'main_lock_must_equal_first_tip'; end if;
   if exists(select 1 from public.goat_bracket_nodes where league_id=lid and goat_bracket_nodes.stage=0 and (starts_at<=now() or starts_at>=c.main_lock_at)) then raise exception 'qualifying_schedule_invalid'; end if;
   if exists(select 1 from public.goat_bracket_nodes x where x.league_id=lid and x.stage<6 and
    (select count(*) from public.goat_bracket_nodes y where y.league_id=lid and (y.home_from=x.id or y.away_from=x.id))<>1) then raise exception 'bracket_feeder_usage_invalid'; end if;
   -- Every actual team occurs once in the tournament field. Main seed slots
   -- reference qualifiers, never duplicate their teams as independent seeds.
   if exists(select team from (select home_team team from public.goat_bracket_nodes where league_id=lid and home_team is not null union all select away_team from public.goat_bracket_nodes where league_id=lid and away_team is not null) x group by team having count(*)>1) then raise exception 'duplicate_tournament_team'; end if;
   update public.goat_leagues set status='open' where id=lid;
  when 'enroll' then
   if l.status<>'open' or c.main_lock_at<=now() then raise exception 'enrollment_closed'; end if;
   insert into public.goat_entries(league_id,user_id) values(lid,actor) on conflict do nothing;
  when 'entry_decide' then
   if l.status<>'open' or c.main_lock_at<=now() then raise exception 'enrollment_closed'; end if;
   update public.goat_entries set status=case when (p->>'approved')::boolean then 'approved' else 'rejected' end where league_id=lid and user_id=(p->>'user_id')::uuid;
   if not found then raise exception 'entry_not_found'; end if;
  when 'bracket_qualifying_pick' then
   select * into n from public.goat_bracket_nodes where id=(p->>'node_id')::uuid;
   if l.status<>'open' or n.stage<>0 or n.starts_at<=now() then raise exception 'selections_locked'; end if;
   if p->>'team' is null or p->>'team' not in (n.home_team,n.away_team) then raise exception 'invalid_bracket_selection'; end if;
   insert into public.goat_bracket_picks(node_id,user_id,team) values(n.id,actor,p->>'team') on conflict(node_id,user_id) do update set team=excluded.team,submitted_at=now();eid:=n.id;
  when 'bracket_submit' then
   if l.status<>'open' or c.main_lock_at<=now() then raise exception 'selections_locked'; end if;
   if jsonb_typeof(p->'picks') is distinct from 'array' or jsonb_array_length(p->'picks')<>63 or
    (select count(distinct x->>'node_id') from jsonb_array_elements(p->'picks') x)<>63 then raise exception 'complete_unique_bracket_required'; end if;
   if p->>'championship_total' is null or (p->>'championship_total')::integer not between 0 and 10000 then raise exception 'championship_total_required'; end if;
   for item in select * from jsonb_array_elements(p->'picks') loop
    select * into n from public.goat_bracket_nodes where id=(item->>'node_id')::uuid and league_id=lid and goat_bracket_nodes.stage>0;
    if n.id is null then raise exception 'game_not_in_bracket'; end if;
    selected:=item->>'team';
    if selected is null then raise exception 'invalid_bracket_selection'; end if;
    if n.stage=1 then
     if not exists(select 1 from public.goat_bracket_candidates(n.id) x where x.team=selected) then raise exception 'invalid_bracket_selection'; end if;
    else
     if not exists(select 1 from jsonb_array_elements(p->'picks') x where (x->>'node_id')::uuid in (n.home_from,n.away_from) and x->>'team'=selected) then raise exception 'inconsistent_bracket_advancement'; end if;
    end if;
   end loop;
   delete from public.goat_bracket_picks k using public.goat_bracket_nodes bn where k.node_id=bn.id and bn.league_id=lid and bn.stage>0 and k.user_id=actor;
   for item in select * from jsonb_array_elements(p->'picks') loop
    insert into public.goat_bracket_picks(node_id,user_id,team) values((item->>'node_id')::uuid,actor,item->>'team');
   end loop;
   insert into public.goat_bracket_submissions(league_id,user_id,championship_total) values(lid,actor,(p->>'championship_total')::integer)
   on conflict(league_id,user_id) do update set championship_total=excluded.championship_total,submitted_at=now();
  when 'bracket_results_import' then
   if jsonb_typeof(p->'results') is distinct from 'array' or jsonb_array_length(p->'results') not between 1 and 95 or
    (select count(distinct x->>'node_id') from jsonb_array_elements(p->'results') x)<>jsonb_array_length(p->'results') then raise exception 'unique_sourced_results_required'; end if;
   for item in select value from jsonb_array_elements(p->'results') order by (select bn.stage from public.goat_bracket_nodes bn where bn.id=(value->>'node_id')::uuid) loop
    if not exists(select 1 from public.goat_bracket_nodes bn where bn.id=(item->>'node_id')::uuid and bn.league_id=lid) then raise exception 'game_not_in_bracket'; end if;
    perform public.goat_command(item||jsonb_build_object('op','bracket_result'));
   end loop;
   eid:=lid;
  when 'bracket_result' then
   select * into n from public.goat_bracket_nodes where id=(p->>'node_id')::uuid;
   if l.status<>'open' or (case when n.stage=0 then n.starts_at else c.main_lock_at end)>now() or n.starts_at>now() then raise exception 'result_not_ready'; end if;
   if n.winner is not null then raise exception 'correction_required'; end if;
   home:=coalesce(n.home_team,(select winner from public.goat_bracket_nodes where id=n.home_from));
   away:=coalesce(n.away_team,(select winner from public.goat_bracket_nodes where id=n.away_from));
   if home is null or away is null then raise exception 'feeder_results_required'; end if;
   if p->>'home_score' is null or p->>'away_score' is null or (p->>'home_score')::integer=(p->>'away_score')::integer or coalesce(p->>'source_url','') not like 'https://%' then raise exception 'sourced_decisive_scores_required'; end if;
   selected:=case when (p->>'home_score')::integer>(p->>'away_score')::integer then home else away end;
   update public.goat_bracket_nodes set winner=selected,home_score=(p->>'home_score')::integer,away_score=(p->>'away_score')::integer,result_source=p->>'source_url',finalized_at=now() where id=n.id;eid:=n.id;
   insert into public.goat_history(league_id,snapshot,reason) values(lid,public.goat_bracket_standings(lid),'bracket_result_finalized');
  when 'bracket_correct' then
   select * into n from public.goat_bracket_nodes where id=(p->>'node_id')::uuid;
   if l.status<>'open' or n.winner is null or coalesce(length(btrim(p->>'reason')),0)=0 then raise exception 'correction_reason_required'; end if;
   insert into public.goat_history(league_id,snapshot,reason) values(lid,public.goat_bracket_standings(lid),'before_bracket_correction');
   with recursive affected as(select n.id union all select x.id from public.goat_bracket_nodes x join affected a on x.home_from=a.id or x.away_from=a.id)
   select jsonb_agg(to_jsonb(x)) into before_result from public.goat_bracket_nodes x join affected a on a.id=x.id;
   with recursive affected as(select n.id union all select x.id from public.goat_bracket_nodes x join affected a on x.home_from=a.id or x.away_from=a.id)
   update public.goat_bracket_nodes set winner=null,home_score=null,away_score=null,result_source=null,finalized_at=null where id in(select id from affected);
   p:=p||jsonb_build_object('previous_results',before_result);eid:=n.id;
   insert into public.goat_history(league_id,snapshot,reason) values(lid,public.goat_bracket_standings(lid),'bracket_correction_invalidated_dependents');
  when 'league_finalize' then
   if l.status<>'open' or exists(select 1 from public.goat_bracket_nodes where league_id=lid and winner is null) or not exists(select 1 from public.goat_entries where league_id=lid and status='approved') then raise exception 'league_incomplete'; end if;
   update public.goat_leagues set status='final' where id=lid;
   insert into public.goat_history(league_id,snapshot,reason) values(lid,public.goat_bracket_standings(lid),'league_finalized');
  else raise exception 'unsupported_bracket_operation';
  end case;
  insert into public.goat_audit(actor_id,action,entity_id,detail) values(actor,op,eid,p);
  return jsonb_build_object('id',eid,'operation',op,'status','recorded');
 elsif l.strategy is not null and l.strategy<>'ranked_ats_v1' then
  -- Preserve source notes on the remaining games; do not accept entries or
  -- run NFL's scoring/deadline code on unfinished competitions.
  if l.owner_id<>actor then raise exception 'commissioner_required' using errcode='42501'; end if;
  if op='league_rules' and l.status='draft' then
   update public.goat_leagues set rules=coalesce(p->'rules','{}')||'{"approved":false}'::jsonb where id=lid;
   insert into public.goat_audit(actor_id,action,entity_id,detail) values(actor,op,lid,p);
   return jsonb_build_object('id',lid,'status','draft');
  end if;
  raise exception 'competition_engine_not_ready';
 end if;
 return public.goat_command_v2(p);
end $$;

create function public.goat_query(p jsonb) returns jsonb language plpgsql stable security definer set search_path='' as $$
declare actor uuid:=public.goat_actor(); lid uuid:=(p->>'league_id')::uuid; l public.goat_leagues; op text:=p->>'op'; result jsonb;
begin
 if lid is not null then select * into l from public.goat_leagues where id=lid; end if;
 if l.strategy='ncaa_bracket_v1' and op in ('league','standings','history') then
  if not public.goat_can_view(lid) then raise exception 'league_access_denied' using errcode='42501'; end if;
  if op='standings' then return public.goat_bracket_standings(lid); end if;
  if op='history' then return public.goat_query_v2(p); end if;
  return jsonb_build_object('league',to_jsonb(l),'server_time',now(),'rounds','[]'::jsonb,'games','[]'::jsonb,'picks','[]'::jsonb,
   'entries',(select coalesce(jsonb_agg(to_jsonb(e)||jsonb_build_object('display_name',g.display_name)),'[]') from public.goat_entries e join public.goat_profiles g on g.user_id=e.user_id where e.league_id=lid),
   'bracket_config',(select to_jsonb(c) from public.goat_bracket_config c where c.league_id=lid),
   'bracket_nodes',(select coalesce(jsonb_agg(to_jsonb(n) order by stage,code),'[]') from public.goat_bracket_nodes n where league_id=lid),
   'bracket_picks',(select coalesce(jsonb_agg(to_jsonb(k)),'[]') from public.goat_bracket_picks k join public.goat_bracket_nodes n on n.id=k.node_id join public.goat_bracket_config c on c.league_id=n.league_id where n.league_id=lid and (k.user_id=actor or (case when n.stage=0 then n.starts_at else c.main_lock_at end)<=now())),
   'bracket_submissions',(select coalesce(jsonb_agg(to_jsonb(s)),'[]') from public.goat_bracket_submissions s join public.goat_bracket_config c on c.league_id=s.league_id where s.league_id=lid and (s.user_id=actor or c.main_lock_at<=now())));
 end if;
 return public.goat_query_v2(p);
end $$;
-- Route the direct standings helper through the same private-league gate.
create or replace function public.goat_standings(lid uuid) returns jsonb language plpgsql stable security definer set search_path='' as $$
declare strategy text;
begin
 perform public.goat_actor();
 if not public.goat_can_view(lid) then raise exception 'league_access_denied' using errcode='42501'; end if;
 select l.strategy into strategy from public.goat_leagues l where id=lid;
 if strategy='ncaa_bracket_v1' then return public.goat_bracket_standings(lid); end if;
 if strategy<>'ranked_ats_v1' then return '[]'; end if;
 return public.goat_standings_internal(lid);
end $$;
revoke all on function public.goat_command(jsonb),public.goat_query(jsonb) from public,anon;
grant execute on function public.goat_command(jsonb),public.goat_query(jsonb) to authenticated;
create or replace function public.goat_health() returns jsonb language sql stable set search_path='' as $$ select '{"database_ok":true,"schema_version":4}'::jsonb; $$;
